head.b:skin:
@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+Bengali:wght@300;400;500;600;700;800&family=Hind+Siliguri:wght@300;400;500;600;700&display=swap');

:root {
  --background: hsl(210 20% 98%);
  --foreground: hsl(220 20% 10%);
  --surface: hsl(0 0% 100%);
  --card: hsl(0 0% 100%);
  --border: hsl(214 20% 88%);
  --header-bg: hsl(220 25% 12%);
  --header-foreground: hsl(0 0% 95%);
  --primary: hsl(215 80% 35%);
  --primary-light: hsl(215 75% 92%);
  --primary-text: hsl(215 80% 30%);
  --news: hsl(215 80% 35%);
  --news-bg: hsl(215 75% 92%);
  --news-text: hsl(215 80% 30%);
  --blog: hsl(152 55% 38%);
  --blog-bg: hsl(152 50% 90%);
  --blog-text: hsl(152 55% 25%);
  --directory: hsl(270 40% 50%);
  --directory-bg: hsl(270 40% 92%);
  --directory-text: hsl(270 40% 30%);
  --muted: hsl(210 15% 93%);
  --muted-foreground: hsl(220 10% 45%);
  --divider-accent: hsl(30 80% 55%);
  --destructive: hsl(0 84% 60%);
  --shadow-sm: 0 1px 3px rgba(21,37,65,0.04);
  --shadow: 0 18px 40px rgba(21,37,65,0.08);
  --shadow-lg: 0 20px 34px rgba(22,37,66,0.08);
  --radius: 18px;
  --radius-sm: 12px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  background:
    radial-gradient(circle at top right, rgba(37,99,235,0.08), transparent 28%),
    radial-gradient(circle at bottom left, rgba(124,58,237,0.07), transparent 24%),
    var(--background);
  color: var(--foreground);
  font-family: 'Hind Siliguri', sans-serif;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--primary); text-decoration: none; transition: color .2s; }
a:hover { color: var(--news); }
img { max-width: 100%; border-radius: 16px; display: block; }

.page-shell { min-height: 100vh; display: flex; flex-direction: column; }
.container { width: min(1180px, calc(100% - 32px)); margin: 0 auto; }

/* ============ HEADER ============ */
.topbar {
  background: var(--header-bg);
  color: var(--header-foreground);
  border-bottom: 1px solid rgba(255,255,255,0.08);
}

.topbar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 18px 0;
}

.brand-block h1,
.brand-block h2,
.brand-block .title {
  margin: 0;
  font-family: 'Noto Sans Bengali', sans-serif;
  font-size: clamp(1.8rem, 4vw, 2.6rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--header-foreground);
}

.brand-block .description {
  margin-top: 6px;
  color: rgba(255,255,255,0.72);
  font-size: 0.96rem;
}

.quick-search {
  min-width: min(360px, 100%);
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.14);
  border-radius: 999px;
  padding: 12px 18px;
  color: rgba(255,255,255,0.82);
  text-align: right;
  font-size: 0.92rem;
  transition: background .2s;
}
.quick-search:focus { background: rgba(255,255,255,0.14); outline: none; }

/* ============ NAV ============ */
.nav-wrap {
  background: rgba(255,255,255,0.96);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 50;
}

.nav-chip-list {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  padding: 14px 0;
}

.nav-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  border-radius: 999px;
  font-family: 'Noto Sans Bengali', sans-serif;
  font-weight: 700;
  font-size: 0.92rem;
  color: var(--foreground);
  background: var(--surface);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-sm);
  transition: transform .2s, box-shadow .2s;
}
.nav-chip:hover { transform: translateY(-1px); box-shadow: var(--shadow); color: var(--foreground); text-decoration: none; }
.chip-news { border-color: color-mix(in srgb, var(--news) 35%, white); }
.chip-blog { border-color: color-mix(in srgb, var(--blog) 35%, white); }
.chip-directory { border-color: color-mix(in srgb, var(--directory) 35%, white); }

/* ============ HERO ============ */
.hero {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(300px, 0.75fr);
  gap: 24px;
  padding: 28px 0;
}

.hero-card,
.content-card,
.sidebar-card,
.footer-card {
  background: rgba(255,255,255,0.92);
  border: 1px solid var(--border);
  border-radius: calc(var(--radius) + 4px);
  box-shadow: var(--shadow);
}

.hero-card {
  padding: 28px;
  background:
    linear-gradient(135deg, rgba(26,82,153,0.06), rgba(18,125,81,0.05)),
    rgba(255,255,255,0.94);
}

.hero-kicker {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-radius: 999px;
  background: var(--news-bg);
  color: var(--news);
  font-weight: 700;
  font-size: 0.92rem;
}

.hero-card h3 {
  margin: 18px 0 10px;
  font-family: 'Noto Sans Bengali', sans-serif;
  font-size: clamp(1.8rem, 4vw, 3rem);
  line-height: 1.15;
}

.hero-card p { margin: 0; color: var(--muted-foreground); font-size: 1rem; }

.hero-side { display: grid; gap: 16px; }

.hero-mini {
  padding: 20px;
  position: relative;
  overflow: hidden;
}
.hero-mini::before {
  content: '';
  position: absolute;
  inset: auto -32px -32px auto;
  width: 120px; height: 120px;
  border-radius: 999px;
  background: rgba(124,58,237,0.08);
}
.hero-mini.blog-accent::before { background: rgba(22,163,74,0.08); }

/* ============ SECTION DIVIDER ============ */
.section-divider {
  display: flex;
  align-items: center;
  gap: 16px;
  margin: 32px 0;
}
.section-divider::before,
.section-divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--divider-accent), transparent);
  opacity: 0.4;
}
.section-divider-text {
  color: var(--divider-accent);
  font-family: 'Noto Sans Bengali', sans-serif;
  font-weight: 800;
  font-size: 1.15rem;
  white-space: nowrap;
}

.section-title {
  margin: 0 0 18px;
  font-family: 'Noto Sans Bengali', sans-serif;
  font-size: 1.4rem;
  font-weight: 800;
}

/* ============ CONTENT GRID ============ */
.content-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 24px;
  padding-bottom: 36px;
}

.content-card { padding: 24px; }
.sidebar-card { padding: 20px; }

/* ============ POSTS ============ */
.post,
.post-outer {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 22px;
  margin-bottom: 18px;
  transition: transform .2s ease, box-shadow .2s ease;
}
.post:hover,
.post-outer:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

h2.post-title,
.post-title {
  font-family: 'Noto Sans Bengali', sans-serif;
  font-size: clamp(1.3rem, 3vw, 2rem);
  line-height: 1.25;
  margin: 0 0 12px;
}
.post-title a { color: var(--foreground); }
.post-title a:hover { color: var(--primary); }

.post-meta, .byline {
  color: var(--muted-foreground);
  font-size: 0.92rem;
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

.post-meta-item {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.post-body, .post-snippet, .entry-content {
  color: var(--foreground);
  font-size: 1rem;
  line-height: 1.8;
}

.post-body img, .entry-content img {
  border-radius: 16px;
  margin: 16px 0;
}

/* ============ CATEGORY TAGS ============ */
.tag-news {
  display: inline-block;
  background: var(--news-bg);
  color: var(--news-text);
  font-size: 0.78rem;
  padding: 3px 10px;
  border-radius: 999px;
  font-weight: 600;
}
.tag-blog {
  display: inline-block;
  background: var(--blog-bg);
  color: var(--blog-text);
  font-size: 0.78rem;
  padding: 3px 10px;
  border-radius: 999px;
  font-weight: 600;
}
.tag-directory {
  display: inline-block;
  background: var(--directory-bg);
  color: var(--directory-text);
  font-size: 0.78rem;
  padding: 3px 10px;
  border-radius: 999px;
  font-weight: 600;
}

/* ============ SHARE BUTTONS ============ */
.share-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid var(--border);
}
.share-bar-label {
  font-family: 'Noto Sans Bengali', sans-serif;
  font-weight: 700;
  font-size: 0.88rem;
  color: var(--muted-foreground);
  margin-right: 4px;
}
.share-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--muted-foreground);
  font-size: 0.9rem;
  cursor: pointer;
  transition: all .2s;
  text-decoration: none;
}
.share-btn:hover { text-decoration: none; }
.share-btn-fb:hover { background: hsl(215 75% 92%); color: hsl(215 80% 45%); border-color: hsl(215 60% 80%); }
.share-btn-tw:hover { background: hsl(200 80% 92%); color: hsl(200 80% 40%); border-color: hsl(200 60% 80%); }
.share-btn-copy:hover { background: var(--muted); color: var(--foreground); }
.share-btn-bookmark {
  margin-left: auto;
  width: auto;
  padding: 0 12px;
  gap: 6px;
  font-weight: 600;
  font-size: 0.82rem;
}
.share-btn-bookmark:hover { background: var(--primary-light); color: var(--primary); border-color: var(--primary); }

.share-count {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.82rem;
  color: var(--muted-foreground);
}

/* ============ COMMENTS ============ */
.comments-section {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 22px;
  margin-top: 18px;
}
.comments-section h4 {
  font-family: 'Noto Sans Bengali', sans-serif;
  font-weight: 800;
  font-size: 1.1rem;
  margin-bottom: 16px;
}
.comment-item {
  padding: 14px 0;
  border-bottom: 1px solid var(--border);
}
.comment-item:last-child { border-bottom: 0; }
.comment-author {
  font-weight: 700;
  font-size: 0.92rem;
  color: var(--foreground);
}
.comment-date {
  font-size: 0.8rem;
  color: var(--muted-foreground);
  margin-left: 8px;
}
.comment-body {
  font-size: 0.95rem;
  margin-top: 6px;
  color: var(--foreground);
  line-height: 1.7;
}
.comment-actions {
  display: flex;
  gap: 12px;
  margin-top: 8px;
}
.comment-action-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.8rem;
  color: var(--muted-foreground);
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 8px;
  transition: all .2s;
}
.comment-action-btn:hover { background: var(--muted); color: var(--primary); }
.comment-reply { margin-left: 24px; border-left: 2px solid var(--border); padding-left: 16px; }
.comment-form textarea {
  width: 100%;
  padding: 12px 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  font-family: 'Hind Siliguri', sans-serif;
  font-size: 0.95rem;
  resize: vertical;
  min-height: 80px;
  transition: border-color .2s;
}
.comment-form textarea:focus { border-color: var(--primary); outline: none; }
.comment-submit-btn {
  margin-top: 8px;
  padding: 10px 20px;
  background: var(--primary);
  color: white;
  border: none;
  border-radius: 999px;
  font-family: 'Noto Sans Bengali', sans-serif;
  font-weight: 700;
  font-size: 0.9rem;
  cursor: pointer;
  transition: opacity .2s;
}
.comment-submit-btn:hover { opacity: 0.9; }

/* ============ MASONRY GRID ============ */
.masonry-section { padding: 16px 0 36px; }
.masonry-grid {
  columns: 4;
  column-gap: 16px;
}
.masonry-item {
  break-inside: avoid;
  margin-bottom: 16px;
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--surface);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-sm);
  transition: transform .3s, box-shadow .3s;
}
.masonry-item:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow);
}
.masonry-item img {
  width: 100%;
  border-radius: 0;
  display: block;
}
.masonry-item-content {
  padding: 14px;
}
.masonry-item-title {
  font-family: 'Noto Sans Bengali', sans-serif;
  font-weight: 700;
  font-size: 0.95rem;
  line-height: 1.35;
  margin-bottom: 6px;
}
.masonry-item-title a { color: var(--foreground); }
.masonry-item-title a:hover { color: var(--primary); }
.masonry-item-excerpt {
  font-size: 0.84rem;
  color: var(--muted-foreground);
  line-height: 1.5;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* ============ WIDGETS ============ */
.widget {
  margin-bottom: 20px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--border);
}
.widget:last-child { border-bottom: 0; margin-bottom: 0; padding-bottom: 0; }

.widget h3, .widget h2 {
  margin: 0 0 14px;
  font-family: 'Noto Sans Bengali', sans-serif;
  font-size: 1.05rem;
  font-weight: 800;
}

.Label a, .PopularPosts .item-title a, .LinkList a {
  display: inline-flex;
  margin: 0 8px 8px 0;
  padding: 8px 12px;
  background: var(--muted);
  border-radius: 999px;
  color: var(--foreground);
  font-size: 0.92rem;
  transition: all .2s;
}
.Label a:hover, .PopularPosts .item-title a:hover, .LinkList a:hover {
  background: var(--primary-light);
  color: var(--primary);
  text-decoration: none;
}

/* ============ FOOTER ============ */
.footer-shell { margin: 0 0 32px; }
.footer-card {
  padding: 24px;
  background: var(--header-bg);
  color: var(--header-foreground);
  border-radius: calc(var(--radius) + 4px);
}
.footer-card a { color: rgba(255,255,255,0.92); }
.copyright { color: rgba(255,255,255,0.68); font-size: 0.92rem; margin-top: 12px; }

/* ============ ANIMATIONS ============ */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}
.animate-fade-in { animation: fadeInUp .4s ease-out both; }

/* ============ BACK TO TOP ============ */
.back-to-top {
  position: fixed;
  bottom: 24px;
  right: 24px;
  width: 44px;
  height: 44px;
  border-radius: 999px;
  background: var(--primary);
  color: white;
  border: none;
  font-size: 1.2rem;
  cursor: pointer;
  box-shadow: var(--shadow);
  display: none;
  align-items: center;
  justify-content: center;
  z-index: 99;
  transition: opacity .3s;
}

/* ============ RESPONSIVE ============ */
@media (max-width: 1024px) {
  .masonry-grid { columns: 3; }
}
@media (max-width: 980px) {
  .hero, .content-grid { grid-template-columns: 1fr; }
  .quick-search { display: none; }
  .masonry-grid { columns: 2; }
}
@media (max-width: 640px) {
  .container { width: min(100% - 20px, 1180px); }
  .topbar-inner { padding: 16px 0; }
  .hero-card, .content-card, .sidebar-card, .footer-card, .post, .post-outer { padding: 18px; }
  .nav-chip-list { gap: 8px; overflow-x: auto; flex-wrap: nowrap; -webkit-overflow-scrolling: touch; padding-bottom: 4px; }
  .nav-chip { white-space: nowrap; flex-shrink: 0; }
  .masonry-grid { columns: 1; }
  .share-bar { flex-wrap: wrap; }
  .share-btn-bookmark { margin-left: 0; width: 100%; justify-content: center; margin-top: 4px; }
  .comment-reply { margin-left: 12px; padding-left: 10px; }
}

body.script:
//
// Copy link
function copyLink(btn) {
  var url = btn.getAttribute('data-url') || window.location.href;
  navigator.clipboard.writeText(url).then(function() {
    btn.textContent = '✅';
    setTimeout(function() { btn.textContent = '🔗'; }, 1500);
  });
}

// Bookmark toggle (localStorage)
function toggleBookmark(btn) {
  var post = btn.closest('.post');
  var title = post ? post.querySelector('.post-title a') : null;
  var url = title ? title.href : window.location.href;
  var key = 'galachipa_bookmarks';
  var bookmarks = JSON.parse(localStorage.getItem(key) || '[]');
  var idx = bookmarks.indexOf(url);
  if (idx > -1) {
    bookmarks.splice(idx, 1);
    btn.textContent = '🔖 বুকমার্ক';
    btn.style.background = '';
    btn.style.color = '';
  } else {
    bookmarks.push(url);
    btn.textContent = '✅ সেভ হয়েছে';
    btn.style.background = 'var(--primary-light)';
    btn.style.color = 'var(--primary)';
  }
  localStorage.setItem(key, JSON.stringify(bookmarks));
}

// Restore bookmark state on load
document.addEventListener('DOMContentLoaded', function() {
  var bookmarks = JSON.parse(localStorage.getItem('galachipa_bookmarks') || '[]');
  document.querySelectorAll('.share-btn-bookmark').forEach(function(btn) {
    var post = btn.closest('.post');
    var title = post ? post.querySelector('.post-title a') : null;
    var url = title ? title.href : '';
    if (bookmarks.indexOf(url) > -1) {
      btn.textContent = '✅ সেভ হয়েছে';
      btn.style.background = 'var(--primary-light)';
      btn.style.color = 'var(--primary)';
    }
  });
});

// Back to top
window.addEventListener('scroll', function() {
  var btn = document.getElementById('backToTop');
  if (btn) btn.style.display = window.scrollY > 400 ? 'flex' : 'none';
});

// Masonry grid via Blogger JSON feed
(function() {
  var masonryEl = document.getElementById('masonry-section');
  if (!masonryEl) return;

  var feedUrl = window.location.origin + '/feeds/posts/default?alt=json&max-results=20';

  fetch(feedUrl)
    .then(function(r) { return r.json(); })
    .then(function(data) {
      var entries = (data.feed && data.feed.entry) || [];
      if (!entries.length) return;

      var grid = document.createElement('div');
      grid.className = 'masonry-grid';

      var ratios = ['56.25%', '75%', '100%', '66.66%'];

      entries.forEach(function(entry, i) {
        var title = entry.title.$t || '';
        var link = '';
        (entry.link || []).forEach(function(l) { if (l.rel === 'alternate') link = l.href; });

        var img = '';
        if (entry.media$thumbnail) {
          img = entry.media$thumbnail.url.replace(/\/s\d+(-c)?\//, '/s600/');
        }

        var snippet = '';
        if (entry.summary) snippet = entry.summary.$t || '';
        else if (entry.content) snippet = entry.content.$t.replace(/<[^>]+>/g, '').slice(0, 120);

        var labels = (entry.category || []).map(function(c) { return c.term; });
        var tagClass = 'tag-news';
        if (labels.indexOf('ব্লগ') > -1) tagClass = 'tag-blog';
        else if (labels.indexOf('ডিরেক্টরি') > -1) tagClass = 'tag-directory';

        var item = document.createElement('div');
        item.className = 'masonry-item animate-fade-in';
        item.style.animationDelay = (i * 50) + 'ms';

        var html = '';
        if (img) {
          var ratio = ratios[i % ratios.length];
          html += '<a href="' + link + '" style="display:block;position:relative;padding-bottom:' + ratio + ';overflow:hidden;">';
          html += '<img src="' + img + '" alt="' + title + '" loading="lazy" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;border-radius:0;"/>';
          html += '</a>';
        }
        html += '<div class="masonry-item-content">';
        if (labels.length) html += '<span class="' + tagClass + '" style="margin-bottom:8px;">' + labels[0] + '</span> ';
        html += '<div class="masonry-item-title"><a href="' + link + '">' + title + '</a></div>';
        if (snippet) html += '<p class="masonry-item-excerpt">' + snippet + '</p>';
        html += '</div>';

        item.innerHTML = html;
        grid.appendChild(item);
      });

      masonryEl.appendChild(grid);
    })
    .catch(function(err) { console.log('Masonry feed error:', err); });
})();
//
